package com.etic.licensecontrol.common;
import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/lookups") public class LookupController {private final CrudService c;LookupController(CrudService c){this.c=c;}@GetMapping("/{type:users|systems|user-types|applications|devices}")List<Map<String,Object>>get(@PathVariable String type,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="0")int page){String sql=switch(type){case"users"->"SELECT Id_User id,CONCAT(TRIM(CONCAT_WS(' ',First_Name,Last_Name,Second_Last_Name)),' (',Username,')') label FROM users WHERE Is_Active=TRUE ORDER BY Username";case"systems"->"SELECT Id_System id,Name label FROM systems WHERE Is_Active=TRUE ORDER BY Name";case"user-types"->"SELECT Id_User_Type id,Name label FROM user_types WHERE Is_Active=TRUE ORDER BY Name";case"applications"->"SELECT Id_Application id,Name label,Licensing_Mode,Status FROM licensed_applications WHERE Is_Active=TRUE ORDER BY Name";default->"SELECT Id_Device id,COALESCE(NULLIF(Display_Name,''),'Sin nombre') label,Status FROM licensed_devices WHERE Is_Active=TRUE ORDER BY Registered_At DESC";};return c.db().queryForList("SELECT * FROM ("+sql+") lookup WHERE label LIKE :search ORDER BY label LIMIT 100 OFFSET :offset",Map.of("search","%"+search+"%","offset",Math.max(page,0)*100));}}
